let _warnedTriangleUV = false;


class Sphere {

	constructor( center = new Vector3(), radius = - 1 ) {

		this.center = center;
		this.radius = radius;

		this._aabbMinX = + Infinity;
		this._aabbMinY = + Infinity;
		this._aabbMinZ = + Infinity;
		this._aabbMaxX = - Infinity;
		this._aabbMaxY = - Infinity;
		this._aabbMaxZ = - Infinity;
		this._rayOriginX = 0;
		this._rayOriginY = 0;
		this._rayOriginZ = 0;
		this._rayDirectionX = 0;
		this._rayDirectionY = 0;
		this._rayDirectionZ = - 1;
		this._planeNormalX = 1;
		this._planeNormalY = 0;
		this._planeNormalZ = 0;
		this._planeConstant = 0;
		this._triAX = 0;
		this._triAY = 0;
		this._triAZ = 0;
		this._triBX = 0;
		this._triBY = 0;
		this._triBZ = 0;
		this._triCX = 0;
		this._triCY = 0;
		this._triCZ = 0;
		this._clipNegRadius = 0;
		this._boundCenterX = 0;
		this._boundCenterY = 0;
		this._boundCenterZ = 0;
		this._boundRadiusSq = 0;
		this._geometryBoundsDirty = true;

	}

	set( center, radius ) {

		this.center.copy( center );
		this.radius = radius;

		return this;

	}

	setFromPoints( points, optionalCenter ) {

		ensureBoxes();
		const center = this.center;

		if ( optionalCenter !== undefined ) {

			center.copy( optionalCenter );

		} else {

			_box.setFromPoints( points ).getCenter( center );

		}

		let maxRadiusSq = 0;

		for ( let i = 0, il = points.length; i < il; i ++ ) {

			maxRadiusSq = Math.max( maxRadiusSq, center.distanceToSquared( points[ i ] ) );

		}

		this.radius = Math.sqrt( maxRadiusSq );

		return this;

